"timeout" | 
/**  数据库错误 */
"database" | 
/**  SSH 相关错误 */
"ssh" | 
/**  终端/PTY 错误 */
"terminal" | 
/**  本地存储 / 凭据库错误 */
"storage" | 
/**  IO 错误 */
"io";

